inline __attribute__((always_inline)) void
__cce_cudaGetOrSetCallConfiguration(dim3 *grid, dim3 *block, int *sharedMem,
                                    void **stream, int type) {
  static thread_local dim3 localGrid = {0, 0, 0};
  static thread_local dim3 localBlock = {0, 0, 0};
  static thread_local int localSharedMem = 0;
  static thread_local void *localStream = 0;
  if (type == 0) {
    localGrid = *grid;
    localBlock = *block;
    localSharedMem = *sharedMem;
    localStream = *stream;
  } else {
    *grid = localGrid;
    *block = localBlock;
    *sharedMem = localSharedMem;
    *stream = localStream;
  }
}

inline __attribute__((alway_inline)) unsigned int
__cce_cudaRtConfigureCall(dim3 grid, dim3 block, int sharedMem = 0,
                          void *stream = 0) {
  __cce_cudaGetOrSetCallConfiguration(&grid, &block, &sharedMem, &stream, 0);
  unsigned int numBlocks = grid.x * grid.y * grid.z;
  return rtConfigureCall(numBlocks, nullptr, stream);
}

inline __attribute__((always_inline)) int __cce_getOrSetBlockNum(int value,
                                                                 int type) {
  static thread_local int local = 0;
  if (type == 0)
    local = value;
  return local;
}

inline __attribute__((always_inline)) unsigned int
__cce_rtConfigureCall(unsigned int numBlocks, void *smDesc = nullptr,
                      void *stream = nullptr) {
  __cce_getOrSetBlockNum(numBlocks, 0);
  return __CCE_RT_CONFIGURE_FUNC_NAME__(numBlocks, smDesc, stream);
}

