#if defined(__cplusplus)
  CCE_FUNC dim3(unsigned int vx = 1, unsigned int vy = 1,
                        unsigned int vz = 1)
      : x(vx), y(vy), z(vz) {}
#endif /* __cplusplus */
};

CCE_INTRINSIC[aicore] int __ffs(long long a) {
  int2 val = (int2 &)a;
  if (val.x == 0 && val.y == 0)
    return 0;
  if (val.x == 0)
    return __builtin_ffs(val.y) + 32;
  else
    return __builtin_ffs(val.x);
}

