template <class T> CCE_INTRINSIC void mem_bar(T mem_type) {
  static_assert(std::is_same<T, __cce_simd::VV_ALL_Type>::value ||
                    std::is_same<T, __cce_simd::VST_VLD_Type>::value ||
                    std::is_same<T, __cce_simd::VLD_VST_Type>::value ||
                    std::is_same<T, __cce_simd::VST_VST_Type>::value ||
                    std::is_same<T, __cce_simd::VS_ALL_Type>::value ||
                    std::is_same<T, __cce_simd::VST_LD_Type>::value ||
                    std::is_same<T, __cce_simd::VLD_ST_Type>::value ||
                    std::is_same<T, __cce_simd::VST_ST_Type>::value ||
                    std::is_same<T, __cce_simd::SV_ALL_Type>::value ||
                    std::is_same<T, __cce_simd::ST_VLD_Type>::value ||
                    std::is_same<T, __cce_simd::LD_VST_Type>::value ||
                    std::is_same<T, __cce_simd::ST_VST_Type>::value,
                INVALID_VALUE_MEM_BAR);
  if (std::is_same<T, __cce_simd::VV_ALL_Type>::value) {
    return __builtin_cce_mem_bar_vv_all();
  } else if (std::is_same<T, __cce_simd::VST_VLD_Type>::value) {
    return __builtin_cce_mem_bar_vst_vld();
  } else if (std::is_same<T, __cce_simd::VLD_VST_Type>::value) {
    return __builtin_cce_mem_bar_vld_vst();
  } else if (std::is_same<T, __cce_simd::VST_VST_Type>::value) {
    return __builtin_cce_mem_bar_vst_vst();
  } else if (std::is_same<T, __cce_simd::VS_ALL_Type>::value) {
    return __builtin_cce_mem_bar_vs_all();
  } else if (std::is_same<T, __cce_simd::VST_LD_Type>::value) {
    return __builtin_cce_mem_bar_vst_ld();
  } else if (std::is_same<T, __cce_simd::VLD_ST_Type>::value) {
    return __builtin_cce_mem_bar_vld_st();
  } else if (std::is_same<T, __cce_simd::VST_ST_Type>::value) {
    return __builtin_cce_mem_bar_vst_st();
  } else if (std::is_same<T, __cce_simd::SV_ALL_Type>::value) {
    return __builtin_cce_mem_bar_sv_all();
  } else if (std::is_same<T, __cce_simd::ST_VLD_Type>::value) {
    return __builtin_cce_mem_bar_st_vld();
  } else if (std::is_same<T, __cce_simd::LD_VST_Type>::value) {
    return __builtin_cce_mem_bar_ld_vst();
