  struct loop_desc {
    uint32_t size : 20;       // Xt[loop4, loop3] Xm[loop2, loop1, loop0]
    uint32_t dst_stride : 20; // LOOPx_STRIDE_NDDMA[20:0]
    uint64_t src_stride : 40; // LOOPx_STRIDE_NDDMA[59:20]
    uint8_t lp_size;          // PAD_CNT_NDDMA[loop4 ~ loop1] Xt[loop0]
    uint8_t rp_size;          // PAD_CNT_NDDMA[loop4 ~ loop1] Xt[loop0]
    CCE_AICORE_INLINE loop_desc(uint32_t size = 1, uint32_t dst_stride = 0,
                                uint32_t src_stride = 0, uint8_t lp_size = 0,
                                uint8_t rp_size = 0)
        : size(size), dst_stride(dst_stride), src_stride(src_stride),
          lp_size(lp_size), rp_size(rp_size) {};
  };

  loop_desc loop4;
  loop_desc loop3;
  loop_desc loop2;
  loop_desc loop1;
  loop_desc loop0;
  enum pad_mode { NEAREST_PADDING_VALUE = 0, CONSTANT_PADDING_VALUE = 1 };
  CCE_AICORE_INLINE nddma_desc() {};
  CCE_AICORE_INLINE nddma_desc(loop_desc loop0) : loop0(loop0) {};
  CCE_AICORE_INLINE nddma_desc(loop_desc loop1, loop_desc loop0)
      : loop1(loop1), loop0(loop0) {};
  CCE_AICORE_INLINE nddma_desc(loop_desc loop2, loop_desc loop1,
                               loop_desc loop0)
      : loop2(loop2), loop1(loop1), loop0(loop0) {};
  CCE_AICORE_INLINE nddma_desc(loop_desc loop3, loop_desc loop2,
                               loop_desc loop1, loop_desc loop0)
      : loop3(loop3), loop2(loop2), loop1(loop1), loop0(loop0) {};
  CCE_AICORE_INLINE nddma_desc(loop_desc loop4, loop_desc loop3,
                               loop_desc loop2, loop_desc loop1,
                               loop_desc loop0)
      : loop4(loop4), loop3(loop3), loop2(loop2), loop1(loop1), loop0(loop0) {};
};

