  return;
}

template <class T = __cce_simd::Mode_Unknown_Type>
CCE_INTRINSIC void vdiv(vector_s16 &dst, vector_s16 src0, vector_s16 src1,
                        vector_bool mask, T mode = __cce_simd::MODE_UNKNOWN) {
  static_assert(mode.value == __cce_simd::MODE_ZEROING.value |
                    mode.value == __cce_simd::MODE_UNKNOWN.value |
                    mode.value == __cce_simd::MODE_MERGING.value,
                INVALID_VALUE_PREDICATE_MODE);
  // x/0 = -1
  vector_bool zero_mask, non_zero_mask, ori_mask, neg_x_mask;
  ori_mask = mask;
  vcmps_eq(zero_mask, src1, 0, mask);
  vector_s16 q_zero, neg_q_zero, pos_q_zero;
  vdup(q_zero, 0x7FFF, mask, __cce_simd::MODE_ZEROING);
  vdup(neg_q_zero, 0x8000, mask, __cce_simd::MODE_ZEROING);
  vcmps_lt(neg_x_mask, src0, 0, mask);
  vsel(q_zero, neg_q_zero, q_zero, neg_x_mask);
  pnot(non_zero_mask, zero_mask, mask);
  mask = non_zero_mask;

  // strip sign
  vector_u16 abs_x;
  vector_u16 abs_y;
  vabs((vector_s16 &)abs_x, src0, mask, __cce_simd::MODE_ZEROING);
  vabs((vector_s16 &)abs_y, src1, mask, __cce_simd::MODE_ZEROING);
  vector_s16 x_xor_y;
  vxor(x_xor_y, src0, src1, mask, __cce_simd::MODE_ZEROING);
  vector_bool p_pos;
  vcmps_ge(p_pos, x_xor_y, 0, mask);

  // reuse vdiv u16
  vector_u16 dst_tmp;
  vdiv(dst_tmp, abs_x, abs_y, mask, __cce_simd::MODE_ZEROING);

  // handle sign
  vector_s16 neg_q;
  vneg(neg_q, (vector_s16)dst_tmp, mask, __cce_simd::MODE_ZEROING);
  vector_s16 q;
  vsel(q, (vector_s16)dst_tmp, neg_q, p_pos);

  vsel(q, q_zero, q, zero_mask);
  mask = ori_mask;

  if (isV920Target()) {
    dst = (mode.value == __cce_simd::MODE_MERGING.value)
              ? __builtin_cce_vsel_v128s16(q, dst, mask)
              : q;
  } else {
    dst = (mode.value == __cce_simd::MODE_MERGING.value)
              ? __builtin_cce_vmov_v128s16_m(dst, q, mask)
              : q;
  }

  return;
}

template <class T = __cce_simd::Mode_Unknown_Type>
CCE_INTRINSIC void vdiv(vector_u32 &dst, vector_u32 src0, vector_u32 src1,
                        vector_bool mask, T mode = __cce_simd::MODE_UNKNOWN) {
  static_assert(mode.value == __cce_simd::MODE_ZEROING.value |
                    mode.value == __cce_simd::MODE_UNKNOWN.value |
                    mode.value == __cce_simd::MODE_MERGING.value,
                INVALID_VALUE_PREDICATE_MODE);
  // x/0 = -1
  vector_bool zero_mask, non_zero_mask, ori_mask;
  ori_mask = mask;
  vcmps_eq(zero_mask, src1, 0, mask);
  vector_u32 q_zero;
  vdup(q_zero, 0xFFFFFFFF, mask, __cce_simd::MODE_ZEROING);
  pnot(non_zero_mask, zero_mask, mask);
  mask = non_zero_mask;

  // Since we need to do interleave, so we temply use PAT_ALL.
  vector_bool pg = pset_b32(__cce_simd::PAT_ALL);
  vector_f32 v_one_f32;
  vector_u32 v_zero_u32;
  vector_f32 v_zero_f32;
  vdup(v_one_f32, (float)1.0, pg, __cce_simd::MODE_ZEROING);
  vdup(v_zero_u32, (uint32_t)0, pg, __cce_simd::MODE_ZEROING);
  vdup(v_zero_f32, (float)0.0, pg, __cce_simd::MODE_ZEROING);

  // convert u32 to f32
  vector_f32 vy_lower_f32;
  vector_f32 vy_higher_f32;
  vector_f32 vy_waste;
  vector_f32 vy_float;
  vector_u32 vy_lower_u32;
  vector_u32 vy_higher_u32;
  vintlv(vy_lower_u32, vy_higher_u32, src1, v_zero_u32);
  vcvt(vy_lower_f32, (vector_s64 &)vy_lower_u32, pg, __cce_simd::ROUND_F,
       __cce_simd::PART_EVEN); // EVEN means lower part
  vcvt(vy_higher_f32, (vector_s64 &)vy_higher_u32, pg, __cce_simd::ROUND_F,
       __cce_simd::PART_EVEN);
  vdintlv(vy_float, vy_waste, vy_lower_f32, vy_higher_f32);

  // Initial estimate of inv(y).
  vector_f32 vy_rec;
  vdiv(vy_rec, v_one_f32, vy_float, pg, __cce_simd::MODE_ZEROING);
  vector_f32 vy_scale;
  vector_u32 v_const;
  vdup(v_const, 0x4F7FFFFEU, pg, __cce_simd::MODE_ZEROING);
  vmul(vy_scale, vy_rec, (vector_f32 &)v_const, pg, __cce_simd::MODE_ZEROING);

  // convert f32 to u32
  vector_u32 z;
  vector_u32 v_waste_u32;
  vector_s64 v_lower_s64;
  vector_s64 v_higher_s64;
  vintlv(vy_lower_f32, vy_higher_f32, vy_scale, v_zero_f32);
  vcvt(v_lower_s64, vy_lower_f32, pg, __cce_simd::ROUND_F,
       __cce_simd::RS_DISABLE, __cce_simd::PART_EVEN); // lower
  vcvt(v_higher_s64, vy_higher_f32, pg, __cce_simd::ROUND_F,
       __cce_simd::RS_DISABLE,
       __cce_simd::PART_EVEN); // lower
  vdintlv(z, v_waste_u32, (vector_u32 &)v_lower_s64,
          (vector_u32 &)v_higher_s64);

  // Strictly limit one iteration of UNR
  vector_u32 tmp_0;
  vmul(tmp_0, z, src1, pg, __cce_simd::MODE_ZEROING);
  vneg((vector_s32 &)tmp_0, (vector_s32)tmp_0, pg, __cce_simd::MODE_ZEROING);
  vector_u32 z_high;
  vector_u32 z_lower;
  vmull(z_lower, z_high, z, tmp_0, pg);
  vadd(z, z, z_high, pg, __cce_simd::MODE_ZEROING);

  // Quotient/remainder estimate.
  vector_u32 q_tmp;
  vector_u32 q_lower;
  vmull(q_lower, q_tmp, src0, z, pg);
  vector_u32 yq_tmp;
  vmul(yq_tmp, q_tmp, src1, mask,
       __cce_simd::MODE_ZEROING); // From here we use mask
                                  // instead of pg.
  vector_u32 r_tmp;
  vsub(r_tmp, src0, yq_tmp, mask, __cce_simd::MODE_ZEROING);

  // Two times of quotient/remainder refinement.
  vector_bool preg_1;
  vcmp_ge(preg_1, r_tmp, src1, mask);
  vsub(r_tmp, r_tmp, src1, preg_1, __cce_simd::MODE_MERGING);
  vadds(q_tmp, q_tmp, 1, preg_1, __cce_simd::MODE_MERGING);
  vcmp_ge(preg_1, r_tmp, src1, mask);
  vsub(r_tmp, r_tmp, src1, preg_1, __cce_simd::MODE_MERGING);
  vadds(q_tmp, q_tmp, 1, preg_1, __cce_simd::MODE_MERGING);

  vsel(q_tmp, q_zero, q_tmp, zero_mask);
  mask = ori_mask;

  if (isV920Target()) {
    dst = (mode.value == __cce_simd::MODE_MERGING.value)
              ? __builtin_cce_vsel_v64u32(q_tmp, dst, mask)
              : q_tmp;
  } else {
    dst = (mode.value == __cce_simd::MODE_MERGING.value)
              ? __builtin_cce_vmov_v64u32_m(dst, q_tmp, mask)
              : q_tmp;
  }
  return;
}

template <class T = __cce_simd::Mode_Unknown_Type>
CCE_INTRINSIC void vdiv(vector_s32 &dst, vector_s32 src0, vector_s32 src1,
                        vector_bool mask, T mode = __cce_simd::MODE_UNKNOWN) {
  static_assert(mode.value == __cce_simd::MODE_ZEROING.value |
                    mode.value == __cce_simd::MODE_UNKNOWN.value |
                    mode.value == __cce_simd::MODE_MERGING.value,
                INVALID_VALUE_PREDICATE_MODE);
  vector_f32 fp32_1;
  vdup(fp32_1, (float)1.0, mask, __cce_simd::MODE_ZEROING);

  // x/0 = -1
  vector_bool zero_mask, non_zero_mask, ori_mask, neg_x_mask;
  ori_mask = mask;
  vcmps_eq(zero_mask, src1, 0, mask);
  vector_s32 q_zero, neg_q_zero, pos_q_zero;
  vdup(q_zero, 0x7fffffff, mask, __cce_simd::MODE_ZEROING);
  vdup(neg_q_zero, 0x80000000, mask, __cce_simd::MODE_ZEROING);
  vcmps_lt(neg_x_mask, src0, 0, zero_mask);
  vsel(q_zero, neg_q_zero, q_zero, neg_x_mask);
  pnot(non_zero_mask, zero_mask, mask);
  mask = non_zero_mask;
  // strip sign
  vector_u32 abs_x;
  vector_u32 abs_y;
  vabs((vector_s32 &)abs_x, src0, mask, __cce_simd::MODE_ZEROING);
  vabs((vector_s32 &)abs_y, src1, mask, __cce_simd::MODE_ZEROING);
  vector_s32 x_xor_y;
  vxor(x_xor_y, src0, src1, mask, __cce_simd::MODE_ZEROING);
  vector_bool p_pos;
  vcmps_ge(p_pos, x_xor_y, 0, mask);

  // Initial estimate of inv(y).
  vector_f32 y_float;
  vfcvt(y_float, (vector_s32)abs_y, mask);
  vector_f32 y_rec;
  vdiv(y_rec, fp32_1, y_float, mask, __cce_simd::MODE_ZEROING);
  vector_u32 f_z_tmp;
  vadds(f_z_tmp, (vector_u32 &)y_rec, 0xffffffeUL, mask,
        __cce_simd::MODE_ZEROING);
  vector_u32 z;

  // to avoid saturation in vfcvt, convert f32 to u32 is conductde here, which
  // is vfcvt((vector_s32 &)z, (vector_f32 &)f_z_tmp, mask, ROUND_F) in pre
  // version,
  vector_f32 vy_lower_f32;
  vector_f32 vy_higher_f32;
  vector_u32 v_waste_u32;
  vector_s64 v_lower_s64;
  vector_s64 v_higher_s64;
  vector_bool high_mask, low_mask, waste_mask;
  pintlv_b32(low_mask, high_mask, mask, waste_mask);
  vintlv((vector_u32 &)vy_lower_f32, (vector_u32 &)vy_higher_f32, f_z_tmp,
         v_waste_u32);
  vcvt(v_lower_s64, vy_lower_f32, low_mask, __cce_simd::ROUND_F,
       __cce_simd::RS_DISABLE,
       __cce_simd::PART_EVEN); // lower
  vcvt(v_higher_s64, vy_higher_f32, high_mask, __cce_simd::ROUND_F,
       __cce_simd::RS_DISABLE,
       __cce_simd::PART_EVEN); // lower
  vdintlv(z, v_waste_u32, (vector_u32 &)v_lower_s64,
          (vector_u32 &)v_higher_s64);
  pdintlv_b32(mask, waste_mask, low_mask, high_mask);

  vector_bool fz_ng_mask;
  vector_u32 z_zero;
  vdup(z_zero, 0, mask, __cce_simd::MODE_ZEROING);
  vcmps_lt(fz_ng_mask, (vector_f32 &)f_z_tmp, (float)0.0, mask);
  vsel(z, z_zero, z, fz_ng_mask);

  // Strictly limit one iteration of UNR
  vector_u32 tmp_0;
  vmul(tmp_0, z, abs_y, mask, __cce_simd::MODE_ZEROING);
  vneg((vector_s32 &)tmp_0, (vector_s32)tmp_0, mask, __cce_simd::MODE_ZEROING);
  vector_u32 z_high;
  vector_u32 z_lower;
  vmull(z_lower, z_high, z, tmp_0, mask);
  vadd(z, z, z_high, mask, __cce_simd::MODE_ZEROING);

  // Quotient/remainder estimate.
  vector_u32 q_tmp;
  vector_u32 q_lower;
  vmull(q_lower, q_tmp, abs_x, z, mask);
  vector_u32 yq_tmp;
  vmul(yq_tmp, q_tmp, abs_y, mask, __cce_simd::MODE_ZEROING);

  vector_u32 r_tmp;
  vector_bool preg_1;
  vsub(r_tmp, abs_x, yq_tmp, mask, __cce_simd::MODE_ZEROING);

  // Two times of quotient/remainder refinement.
  vcmp_ge(preg_1, r_tmp, abs_y, mask);
  vsub(r_tmp, r_tmp, abs_y, preg_1, __cce_simd::MODE_MERGING);
  vadds(q_tmp, q_tmp, 1, preg_1, __cce_simd::MODE_MERGING);
  vcmp_ge(preg_1, r_tmp, abs_y, mask);
  vsub(r_tmp, r_tmp, abs_y, preg_1, __cce_simd::MODE_MERGING);
  vadds(q_tmp, q_tmp, 1, preg_1, __cce_simd::MODE_MERGING);

  // handle sign
  vector_s32 neg_q;
  vneg(neg_q, (vector_s32)q_tmp, mask, __cce_simd::MODE_ZEROING);
  vector_s32 q;
  vsel(q, (vector_s32)q_tmp, neg_q, p_pos);
  vsel(q, q_zero, q, zero_mask);

  mask = ori_mask;
  if (isV920Target()) {
    dst = (mode.value == __cce_simd::MODE_MERGING.value)
              ? __builtin_cce_vsel_v64u32(q, dst, mask)
              : q;
  } else {
    dst = (mode.value == __cce_simd::MODE_MERGING.value)
              ? __builtin_cce_vmov_v64u32_m(dst, q, mask)
              : q;
  }
  return;
}

template <class T = __cce_simd::Mode_Unknown_Type>
CCE_INTRINSIC void vdiv(vector_f32 &dst, vector_f32 src0, vector_f32 src1,
                        vector_bool mask, T mode = __cce_simd::MODE_UNKNOWN) {
  // neg_zero = tbe.broadcast(tvm.const(-0.0, "float32"), shape_max)
  vector_f32 neg_zero_vec;
  vdup(neg_zero_vec, (-0.0f), mask, __cce_simd::MODE_ZEROING);

  // one = tbe.broadcast(tvm.const(1.0, "float32"), shape_max)
  vector_f32 one_vec;
  vdup(one_vec, (1.0f), mask, __cce_simd::MODE_ZEROING);

  // a_signbit = vand(a, neg_zero)
  vector_f32 a_sign;
  vand(a_sign, src0, neg_zero_vec, mask, __cce_simd::MODE_ZEROING);

  // one_temp = vor(one, a_signbit)
  vector_f32 one_tmp = one_vec;
  vor(one_tmp, one_vec, a_sign, mask, __cce_simd::MODE_ZEROING);

  // x1 = div(a, b)
  vector_f32 x1;
  ::vdiv(x1, src0, src1, mask, __cce_simd::MODE_ZEROING);

  // b_temp = -1.0*b
  vector_f32 b_temp;
  vmuls(b_temp, src1, float(-1.0), mask, __cce_simd::MODE_ZEROING);

  // a = fma(a, b_temp, x1) // a = a + b_temp*x1
  vector_f32 tmp_0, tmp_src0 = src0;
  vmula(tmp_src0, b_temp, x1, mask, __cce_simd::MODE_ZEROING);

  // temp_mask = tbe.vcmp(a, a, "eq", "bit")??
  vector_bool tmp_mask;
  vcmp_eq(tmp_mask, tmp_src0, tmp_src0, mask);

  // temp_a = tbe.vsel(temp_mask, a, one_temp)
  vector_f32 tmp_1;
  vsel(tmp_1, tmp_src0, one_tmp, tmp_mask);

  // e = div(temp_a, b)
  ::vdiv(tmp_0, tmp_1, src1, mask, __cce_simd::MODE_ZEROING);

  // x = x1 + e
  vector_f32 q;
  vadd(q, x1, tmp_0, mask, __cce_simd::MODE_ZEROING);
  if (isV920Target()) {
    dst = (mode.value == __cce_simd::MODE_MERGING.value)
              ? __builtin_cce_vsel_v64u32(q, dst, mask)
              : q;
  } else {
    dst = (mode.value == __cce_simd::MODE_MERGING.value)
              ? __builtin_cce_vmov_v64u32_m(dst, q, mask)
              : q;
  }
  return;
}

template <class T>
CCE_INTRINSIC void vdup(vector_bf16 &dst, bfloat16_t src, vector_bool mask,
                        T mode) {
  static_assert(mode.value == __cce_simd::MODE_MERGING.value ||
                    mode.value == __cce_simd::MODE_ZEROING.value,
                "The 4th argument of this vdup can only be: "
