template <DivisionMode div_mode = DivisionMode::DIV_FLOOR,
          class T = __cce_simd::Mode_Unknown_Type>
CCE_INTRINSIC void vmod(vector_u16 &dst, vector_u16 src0, vector_u16 src1,
                        vector_bool mask, T mode = __cce_simd::MODE_UNKNOWN) {
  static_assert(mode.value == __cce_simd::MODE_ZEROING.value |
                    mode.value == __cce_simd::MODE_UNKNOWN.value |
                    mode.value == __cce_simd::MODE_MERGING.value,
                INVALID_VALUE_PREDICATE_MODE);
  // x/0 = -1
  vector_bool zero_mask, non_zero_mask, ori_mask;
  ori_mask = mask;
  vcmps_eq(zero_mask, src1, 0, mask);
  vector_u16 r_zero;
  vdup(r_zero, 0xFFFF, mask, __cce_simd::MODE_ZEROING);
  pnot(non_zero_mask, zero_mask, mask);
  mask = non_zero_mask;

  // Since we need to do interleave, so we temply use PAT_ALL.
  vector_bool pg = pset_b32(__cce_simd::PAT_ALL);
  vector_f32 v_one_f32;
  vector_u16 v_zero_u16;
  vector_f32 v_zero_f32;
  vdup(v_one_f32, (float)1.0, pg, __cce_simd::MODE_ZEROING);
  vdup(v_zero_u16, (uint16_t)0, pg, __cce_simd::MODE_ZEROING);
  vdup(v_zero_f32, (float)0.0, pg, __cce_simd::MODE_ZEROING);

  // convert u16 to f32
  vector_f32 vy_lower_f32;
  vector_f32 vy_higher_f32;
  vector_u16 vy_lower_u16;
  vector_u16 vy_higher_u16;
  vintlv(vy_lower_u16, vy_higher_u16, src1, v_zero_u16);
  vcvt(vy_lower_f32, (vector_s32 &)vy_lower_u16, pg, __cce_simd::ROUND_F);
  vcvt(vy_higher_f32, (vector_s32 &)vy_higher_u16, pg, __cce_simd::ROUND_F);

  // Initial estimate of inv(y).
  vector_f32 vy_rec_lower;
  vector_f32 vy_rec_higher;
  vdiv(vy_rec_lower, v_one_f32, vy_lower_f32, pg, __cce_simd::MODE_ZEROING);
  vdiv(vy_rec_higher, v_one_f32, vy_higher_f32, pg, __cce_simd::MODE_ZEROING);
  vector_f32 vy_scale_lower;
  vector_f32 vy_scale_higher;
  vector_u32 v_const;
  // Since f32 can fully cover the numerical range of u16,
  // we use 2^16 for the initial value calculation.
  vdup(v_const, 0x47800000U, pg, __cce_simd::MODE_ZEROING);
  vmul(vy_scale_lower, vy_rec_lower, (vector_f32 &)v_const, pg,
       __cce_simd::MODE_ZEROING);
  vmul(vy_scale_higher, vy_rec_higher, (vector_f32 &)v_const, pg,
       __cce_simd::MODE_ZEROING);

  // trick: no need to do f32->u16, we can fully reuse s32 to do vmull(u16).
  vector_s32 v_lower_s32;
  vector_s32 v_higher_s32;
  vcvt(v_lower_s32, vy_scale_lower, pg, __cce_simd::ROUND_F,
       __cce_simd::RS_DISABLE);
  vcvt(v_higher_s32, vy_scale_higher, pg, __cce_simd::ROUND_F,
       __cce_simd::RS_DISABLE);

  // Quotient/remainder estimate.
  // vmull(u16)
  vector_u32 q_tmp_lower;
  vector_u32 q_tmp_higher;
  vector_u16 vx_lower_u16;
  vector_u16 vx_higher_u16;
  vector_u16 q_tmp;
  vector_u16 q_lower;
  vintlv(vx_lower_u16, vx_higher_u16, src0, v_zero_u16);
  vmul(q_tmp_lower, (vector_u32 &)v_lower_s32, (vector_u32 &)vx_lower_u16, pg,
       __cce_simd::MODE_ZEROING);
  vmul(q_tmp_higher, (vector_u32 &)v_higher_s32, (vector_u32 &)vx_higher_u16,
       pg, __cce_simd::MODE_ZEROING);
  vdintlv(q_lower, q_tmp, (vector_u16 &)q_tmp_lower,
          (vector_u16 &)q_tmp_higher);

  vector_u16 yq_tmp;
  vmul(yq_tmp, q_tmp, src1, mask, __cce_simd::MODE_ZEROING);
  vector_u16 r_tmp;
  vsub(r_tmp, src0, yq_tmp, mask, __cce_simd::MODE_ZEROING);

  // Two times of quotient/remainder refinement.
  vector_bool preg_1;
  vcmp_ge(preg_1, r_tmp, src1, mask);
  vsub(r_tmp, r_tmp, src1, preg_1, __cce_simd::MODE_MERGING);
  vadds(q_tmp, q_tmp, 1, preg_1, __cce_simd::MODE_MERGING);
  vcmp_ge(preg_1, r_tmp, src1, mask);
  vsub(r_tmp, r_tmp, src1, preg_1, __cce_simd::MODE_MERGING);
  vadds(q_tmp, q_tmp, 1, preg_1, __cce_simd::MODE_MERGING);

  vsel(r_tmp, r_zero, r_tmp, zero_mask);
  mask = ori_mask;
  if (isV920Target()) {
    dst = (mode.value == __cce_simd::MODE_MERGING.value)
              ? __builtin_cce_vsel_v128u16(r_tmp, dst, mask)
              : r_tmp;
  } else {
    dst = (mode.value == __cce_simd::MODE_MERGING.value)
              ? __builtin_cce_vmov_v128u16_m(dst, r_tmp, mask)
              : r_tmp;
  }

  return;
}

template <DivisionMode div_mode = DivisionMode::DIV_FLOOR,
          class T = __cce_simd::Mode_Unknown_Type>
CCE_INTRINSIC void vmod(vector_s16 &dst, vector_s16 src0, vector_s16 src1,
                        vector_bool mask, T mode = __cce_simd::MODE_UNKNOWN) {
  static_assert(mode.value == __cce_simd::MODE_ZEROING.value |
                    mode.value == __cce_simd::MODE_UNKNOWN.value |
                    mode.value == __cce_simd::MODE_MERGING.value,
                INVALID_VALUE_PREDICATE_MODE);
  // x/0 = -1
  vector_bool zero_mask, non_zero_mask, ori_mask;
  ori_mask = mask;
  vcmps_eq(zero_mask, src1, 0, mask);
  vector_s16 r_zero;
  vdup(r_zero, -1, mask, __cce_simd::MODE_ZEROING);
  pnot(non_zero_mask, zero_mask, mask);
  mask = non_zero_mask;

  // strip sign
  vector_u16 abs_x;
  vector_u16 abs_y;
  vabs((vector_s16 &)abs_x, src0, mask, __cce_simd::MODE_ZEROING);
  vabs((vector_s16 &)abs_y, src1, mask, __cce_simd::MODE_ZEROING);
  vector_s16 x_xor_y;
  vxor(x_xor_y, src0, src1, mask, __cce_simd::MODE_ZEROING);
  vector_bool p_pos;
  vcmps_ge(p_pos, x_xor_y, 0, mask);

  // reuse vdiv u16
  vector_u16 dst_tmp;
  vdiv(dst_tmp, abs_x, abs_y, mask, __cce_simd::MODE_ZEROING);

  // handle sign
  vector_s16 neg_q;
  vneg(neg_q, (vector_s16)dst_tmp, mask, __cce_simd::MODE_ZEROING);
  vector_s16 q;
  vsel(q, (vector_s16)dst_tmp, neg_q, p_pos);

  /**
    since q is obtained.
      r = x - q*y
        sign of x,y is same: r=r
        sign of x,y is different r = y + r
  */
  vector_s16 qy, r;
  vmul(qy, q, src1, mask, __cce_simd::MODE_ZEROING);
  vsub(r, src0, qy, mask, __cce_simd::MODE_ZEROING);

  vector_bool no_zreo_r, sign_x, sign_y, sign_diff;
  vcmps_ne(no_zreo_r, r, 0, mask);
  vcmps_ge(sign_x, src0, 0, mask);
  vcmps_ge(sign_y, src1, 0, mask);
  pxor(sign_diff, sign_x, sign_y,
       mask); // sign_diff =1 means the sign of x and y is different.

  if (div_mode == DivisionMode::DIV_FLOOR) {
    vector_bool need_amend;
    pand(need_amend, sign_diff, no_zreo_r, mask);
    vadd(r, src1, r, need_amend, __cce_simd::MODE_MERGING);
  }
  vsel(r, r_zero, r, zero_mask);
  mask = ori_mask;

  if (isV920Target()) {
    dst = (mode.value == __cce_simd::MODE_MERGING.value)
              ? __builtin_cce_vsel_v128s16(r, dst, mask)
              : r;
  } else {
    dst = (mode.value == __cce_simd::MODE_MERGING.value)
              ? __builtin_cce_vmov_v128s16_m(dst, r, mask)
              : r;
  }
  return;
}

template <DivisionMode div_mode = DivisionMode::DIV_FLOOR,
          class T = __cce_simd::Mode_Unknown_Type>
CCE_INTRINSIC void vmod(vector_u32 &dst, vector_u32 src0, vector_u32 src1,
                        vector_bool mask, T mode = __cce_simd::MODE_UNKNOWN) {
  static_assert(mode.value == __cce_simd::MODE_ZEROING.value |
                    mode.value == __cce_simd::MODE_UNKNOWN.value |
                    mode.value == __cce_simd::MODE_MERGING.value,
                INVALID_VALUE_PREDICATE_MODE);
  // x % 0 = -1
  vector_bool zero_mask, non_zero_mask, ori_mask;
  ori_mask = mask;
  vcmps_eq(zero_mask, src1, 0, mask);
  vector_u32 r_zero;
  vdup(r_zero, 0xFFFFFFFF, mask, __cce_simd::MODE_ZEROING);
  pnot(non_zero_mask, zero_mask, mask);
  mask = non_zero_mask;

  // Since we need to do interleave, so we temply use PAT_ALL.
  vector_bool pg = pset_b32(__cce_simd::PAT_ALL);
  vector_f32 v_one_f32;
  vector_u32 v_zero_u32;
  vector_f32 v_zero_f32;
  vdup(v_one_f32, (float)1.0, pg, __cce_simd::MODE_ZEROING);
  vdup(v_zero_u32, (uint32_t)0, pg, __cce_simd::MODE_ZEROING);
  vdup(v_zero_f32, (float)0.0, pg, __cce_simd::MODE_ZEROING);

  // convert u32 to f32
  vector_f32 vy_lower_f32;
  vector_f32 vy_higher_f32;
  vector_f32 vy_waste;
  vector_f32 vy_float;
  vector_u32 vy_lower_u32;
  vector_u32 vy_higher_u32;
  vintlv(vy_lower_u32, vy_higher_u32, src1, v_zero_u32);
  vcvt(vy_lower_f32, (vector_s64 &)vy_lower_u32, pg, __cce_simd::ROUND_F,
       __cce_simd::PART_EVEN); // EVEN means lower part
  vcvt(vy_higher_f32, (vector_s64 &)vy_higher_u32, pg, __cce_simd::ROUND_F,
       __cce_simd::PART_EVEN);
  vdintlv(vy_float, vy_waste, vy_lower_f32, vy_higher_f32);

  // Initial estimate of inv(y).
  vector_f32 vy_rec;
  vdiv(vy_rec, v_one_f32, vy_float, pg, __cce_simd::MODE_ZEROING);
  vector_f32 vy_scale;
  vector_u32 v_const;
  vdup(v_const, 0x4F7FFFFEU, pg, __cce_simd::MODE_ZEROING);
  vmul(vy_scale, vy_rec, (vector_f32 &)v_const, pg, __cce_simd::MODE_ZEROING);

  // convert f32 to u32
  vector_u32 z;
  vector_u32 v_waste_u32;
  vector_s64 v_lower_s64;
  vector_s64 v_higher_s64;
  vintlv(vy_lower_f32, vy_higher_f32, vy_scale, v_zero_f32);
  vcvt(v_lower_s64, vy_lower_f32, pg, __cce_simd::ROUND_F,
       __cce_simd::RS_DISABLE, __cce_simd::PART_EVEN); // lower
  vcvt(v_higher_s64, vy_higher_f32, pg, __cce_simd::ROUND_F,
       __cce_simd::RS_DISABLE,
       __cce_simd::PART_EVEN); // lower
  vdintlv(z, v_waste_u32, (vector_u32 &)v_lower_s64,
          (vector_u32 &)v_higher_s64);

  // Strictly limit one iteration of UNR
  vector_u32 tmp_0;
  vmul(tmp_0, z, src1, pg, __cce_simd::MODE_ZEROING);
  vneg((vector_s32 &)tmp_0, (vector_s32)tmp_0, pg, __cce_simd::MODE_ZEROING);
  vector_u32 z_high;
  vector_u32 z_lower;
  vmull(z_lower, z_high, z, tmp_0, pg);
  vadd(z, z, z_high, pg, __cce_simd::MODE_ZEROING);

  // Quotient/remainder estimate.
  vector_u32 q_tmp;
  vector_u32 q_lower;
  vmull(q_lower, q_tmp, src0, z, pg);
  vector_u32 yq_tmp;
  vmul(yq_tmp, q_tmp, src1, mask,
       __cce_simd::MODE_ZEROING); // From here we use mask
                                  // instead of pg.
  vector_u32 r_tmp;
  vsub(r_tmp, src0, yq_tmp, mask, __cce_simd::MODE_ZEROING);

  // Two times of quotient/remainder refinement.
  vector_bool preg_1;
  vcmp_ge(preg_1, r_tmp, src1, mask);
  vsub(r_tmp, r_tmp, src1, preg_1, __cce_simd::MODE_MERGING);
  vadds(q_tmp, q_tmp, 1, preg_1, __cce_simd::MODE_MERGING);
  vcmp_ge(preg_1, r_tmp, src1, mask);
  vsub(r_tmp, r_tmp, src1, preg_1, __cce_simd::MODE_MERGING);
  vadds(q_tmp, q_tmp, 1, preg_1, __cce_simd::MODE_MERGING);

  vsel(r_tmp, r_zero, r_tmp, zero_mask);
  mask = ori_mask;

  if (isV920Target()) {
    dst = (mode.value == __cce_simd::MODE_MERGING.value)
              ? __builtin_cce_vsel_v64u32(r_tmp, dst, mask)
              : r_tmp;
  } else {
    dst = (mode.value == __cce_simd::MODE_MERGING.value)
              ? __builtin_cce_vmov_v64u32_m(dst, r_tmp, mask)
              : r_tmp;
  }

  return;
}

template <DivisionMode div_mode = DivisionMode::DIV_FLOOR,
          class T = __cce_simd::Mode_Unknown_Type>
CCE_INTRINSIC void vmod(vector_s32 &dst, vector_s32 src0, vector_s32 src1,
                        vector_bool mask, T mode = __cce_simd::MODE_UNKNOWN) {
  static_assert(mode.value == __cce_simd::MODE_ZEROING.value |
                    mode.value == __cce_simd::MODE_UNKNOWN.value |
                    mode.value == __cce_simd::MODE_MERGING.value,
                INVALID_VALUE_PREDICATE_MODE);
  vector_f32 fp32_1;
  vdup(fp32_1, (float)1.0, mask, __cce_simd::MODE_ZEROING);

  // x//0 = -1
  vector_bool zero_mask, non_zero_mask, ori_mask;
  ori_mask = mask;
  vcmps_eq(zero_mask, src1, 0, mask);
  vector_s32 r_zero;
  vdup(r_zero, -1, mask, __cce_simd::MODE_ZEROING);
  pnot(non_zero_mask, zero_mask, mask);
  mask = non_zero_mask;

  // strip sign
  vector_u32 abs_x;
  vector_u32 abs_y;
  vabs((vector_s32 &)abs_x, src0, mask, __cce_simd::MODE_ZEROING);
  vabs((vector_s32 &)abs_y, src1, mask, __cce_simd::MODE_ZEROING);
  vector_s32 x_xor_y;
  vxor(x_xor_y, src0, src1, mask, __cce_simd::MODE_ZEROING);
  vector_bool p_pos;
  vcmps_ge(p_pos, x_xor_y, 0, mask);

  // Initial estimate of inv(y).
  vector_f32 y_float;
  vfcvt(y_float, (vector_s32)abs_y, mask);
  vector_f32 y_rec;
  vdiv(y_rec, fp32_1, y_float, mask, __cce_simd::MODE_ZEROING);
  vector_u32 f_z_tmp;
  vadds(f_z_tmp, (vector_u32 &)y_rec, 0xffffffeUL, mask,
        __cce_simd::MODE_ZEROING);
  vector_u32 z;

  // convert f32 to u32
  vector_f32 vy_lower_f32;
  vector_f32 vy_higher_f32;
  vector_u32 v_waste_u32;
  vector_s64 v_lower_s64;
  vector_s64 v_higher_s64;
  vector_bool high_mask, low_mask, waste_mask;
  pintlv_b32(low_mask, high_mask, mask, waste_mask);
  vintlv((vector_u32 &)vy_lower_f32, (vector_u32 &)vy_higher_f32, f_z_tmp,
         v_waste_u32);
  vcvt(v_lower_s64, vy_lower_f32, low_mask, __cce_simd::ROUND_F,
       __cce_simd::RS_DISABLE,
       __cce_simd::PART_EVEN); // lower
  vcvt(v_higher_s64, vy_higher_f32, high_mask, __cce_simd::ROUND_F,
       __cce_simd::RS_DISABLE,
       __cce_simd::PART_EVEN); // lower
  vdintlv(z, v_waste_u32, (vector_u32 &)v_lower_s64,
          (vector_u32 &)v_higher_s64);
  pdintlv_b32(mask, waste_mask, low_mask, high_mask);

  // Strictly limit one iteration of UNR
  vector_u32 tmp_0;
  vmul(tmp_0, z, abs_y, mask, __cce_simd::MODE_ZEROING);
  vneg((vector_s32 &)tmp_0, (vector_s32)tmp_0, mask, __cce_simd::MODE_ZEROING);
  vector_u32 z_high;
  vector_u32 z_lower;
  vmull(z_lower, z_high, z, tmp_0, mask);
  vadd(z, z, z_high, mask, __cce_simd::MODE_ZEROING);

  // Quotient/remainder estimate.
  vector_u32 q_tmp;
  vector_u32 q_lower;
  vmull(q_lower, q_tmp, abs_x, z, mask);
  vector_u32 yq_tmp;
  vmul(yq_tmp, q_tmp, abs_y, mask, __cce_simd::MODE_ZEROING);

  vector_u32 r_tmp;
  vector_bool preg_1;
  vsub(r_tmp, abs_x, yq_tmp, mask, __cce_simd::MODE_ZEROING);

  // Two times of quotient/remainder refinement.
  vcmp_ge(preg_1, r_tmp, abs_y, mask);
  vsub(r_tmp, r_tmp, abs_y, preg_1, __cce_simd::MODE_MERGING);
  vadds(q_tmp, q_tmp, 1, preg_1, __cce_simd::MODE_MERGING);
  vcmp_ge(preg_1, r_tmp, abs_y, mask);
  vsub(r_tmp, r_tmp, abs_y, preg_1, __cce_simd::MODE_MERGING);
  vadds(q_tmp, q_tmp, 1, preg_1, __cce_simd::MODE_MERGING);

  // handle sign
  vector_s32 neg_q;
  vneg(neg_q, (vector_s32)q_tmp, mask, __cce_simd::MODE_ZEROING);
  vector_s32 q;
  vsel(q, (vector_s32)q_tmp, neg_q, p_pos);

  /**
    since q is obtained.
      r = x - q*y
        sign of x,y is same: r=r
        sign of x,y is different r = y + r
  */
  vector_s32 qy, r;
  vmul(qy, q, src1, mask, __cce_simd::MODE_ZEROING);
  vsub(r, src0, qy, mask, __cce_simd::MODE_ZEROING);

  vector_bool no_zreo_r, sign_x, sign_y, sign_diff;
  vcmps_ne(no_zreo_r, r_tmp, 0, mask);
  vcmps_ge(sign_x, src0, 0, mask);
  vcmps_ge(sign_y, src1, 0, mask);
  pxor(sign_diff, sign_x, sign_y,
       mask); // sign_diff =1 means the sign of x and y is different.

  if (div_mode == DivisionMode::DIV_FLOOR) {
    vector_bool need_amend;
    pand(need_amend, sign_diff, no_zreo_r, mask);
    vadd(r, src1, r, need_amend, __cce_simd::MODE_MERGING);
  }

  vsel(r, r_zero, r, zero_mask);
  mask = ori_mask;

  if (isV920Target()) {
    dst = (mode.value == __cce_simd::MODE_MERGING.value)
              ? __builtin_cce_vsel_v64u32(r, dst, mask)
              : r;
  } else {
    dst = (mode.value == __cce_simd::MODE_MERGING.value)
              ? __builtin_cce_vmov_v64u32_m(dst, r, mask)
              : r;
  }

  return;
}

