CCE_INTRINSIC void vmuls(vector_bf16 &dst, vector_bf16 src0, bfloat16_t scalar,
                         vector_bool mask, T mode = __cce_simd::MODE_ZEROING) {
  static_assert(mode.value == __cce_simd::MODE_ZEROING.value |
